    'onboarding_nudge_body_1' => 'Je hebt een account aangemaakt maar nog geen schema ingesteld. Het kost ongeveer een minuut: kies of je een artiest, locatie of curator bent, en je openbare pagina staat live.',
    'onboarding_nudge_subject_2' => 'Hulp nodig bij het instellen van je schema?',
    'onboarding_nudge_heading_2' => 'We helpen je graag',
    'onboarding_nudge_body_2' => 'Je account is klaar maar er staat nog geen schema op. Kies het passende type en je krijgt een deelbare pagina voor je evenementen, tweewegs agendasynchronisatie en een agenda die je op je eigen site kunt insluiten.',
